  IonSearchbar,
  SearchbarInputEventDetail,
  RefresherEventDetail
} from '@ionic/react';
import { useIonViewWillEnter } from '@ionic/react-hooks';
import { addOutline, createOutline, trashOutline, closeOutline, barChartOutline } from 'ionicons/icons';
import {
  FactoryRunUsage,
  getAllFactoryRunUsages,
  createFactoryRunUsage,
  updateFactoryRunUsage,
  deleteFactoryRunUsage
} from '../api/factoryRunUsageApi';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';

import './FactoryRunUsagePage.css';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const FactoryRunUsagePage: React.FC = () => {
  const { roleCode } = useUser();
  const isAdmin = roleCode === 'admin';

  const [factoryRunUsages, setFactoryRunUsages] = useState<FactoryRunUsage[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedUsage, setSelectedUsage] = useState<FactoryRunUsage | null>(null);
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);

  const initialFormState: Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at"> = {
    factoryRunRef: '',
    promptTokens: 0,
    completionTokens: 0,
    totalTokens: 0,
    costUSD: 0,
    modelName: '',
    timestamp: new Date().toISOString()
  };
  const [formState, setFormState] = useState(initialFormState);

  // Pagination states
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);
  const [hasMore, setHasMore] = useState(true);

  // Popover state for Header
  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const contentRef = useRef<HTMLIonContentElement>(null);

  const loadFactoryRunUsages = async (initialLoad = true, pageNum = 1) => {
    if (loading) return;
    setLoading(true);
    setError('');

    try {
      const allUsages = await getAllFactoryRunUsages();
      const filteredUsages = allUsages.filter(usage =>
        usage.factoryRunRef.toLowerCase().includes(searchTerm.toLowerCase()) ||
        usage.modelName.toLowerCase().includes(searchTerm.toLowerCase())
      ).sort((a, b) => new Date(b.created_At).getTime() - new Date(a.created_At).getTime()); // Sort by created_At desc

      if (initialLoad) {
        setFactoryRunUsages(filteredUsages.slice(0, pageSize));
        setPage(1);
      } else {
        setFactoryRunUsages(prev => [...prev, ...filteredUsages.slice((pageNum - 1) * pageSize, pageNum * pageSize)]);
      }
      setHasMore(filteredUsages.length > pageNum * pageSize);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading factory run usages.');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    loadFactoryRunUsages(true);
  }, [searchTerm]);

  const doRefresh = async (event: CustomEvent<RefresherEventDetail>) => {
    await loadFactoryRunUsages(true);
    event.detail.complete();
  };

  const loadMoreItems = async (event: CustomEvent<void>) => {
    if (!hasMore || loading) {
      (event.target as HTMLIonInfiniteScrollElement).complete();
      return;
    }
    const nextPage = page + 1;
    await loadFactoryRunUsages(false, nextPage);
    setPage(nextPage);
    (event.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleSearch = (e: CustomEvent<SearchbarInputEventDetail>) => {
    setSearchTerm(e.detail.value || '');
    setFactoryRunUsages([]); // Clear current list to force re-load from beginning
    setPage(1);
    setHasMore(true);
  };

  const openCreateModal = () => {
    setIsEditing(false);
    setFormState({ ...initialFormState, timestamp: new Date().toISOString() });
    setShowFormModal(true);
  };

  const openEditModal = (usage: FactoryRunUsage) => {
    setIsEditing(true);
    setSelectedUsage(usage);
    setFormState({
      factoryRunRef: usage.factoryRunRef,
      promptTokens: usage.promptTokens,
      completionTokens: usage.completionTokens,
      totalTokens: usage.totalTokens,
      costUSD: usage.costUSD,
      modelName: usage.modelName,
      timestamp: usage.timestamp,
    });
    setShowFormModal(true);
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      const payload = {
        ...formState,
        // Ensure tokens are numbers, costUSD is a number
        promptTokens: Number(formState.promptTokens),
        completionTokens: Number(formState.completionTokens),
        totalTokens: Number(formState.totalTokens),
        costUSD: Number(formState.costUSD),
        // timestamp needs to be a valid ISO string for the backend
        timestamp: new Date(formState.timestamp).toISOString(),
      };

      if (isEditing && selectedUsage) {
        await updateFactoryRunUsage(selectedUsage.factoryRunUsageId, payload);
      } else {
        await createFactoryRunUsage(payload);
      }
      setShowFormModal(false);
      await loadFactoryRunUsages(true); // Reload data
      setError('Uso de Factory Run guardado exitosamente.');
    } catch (err) {
      setError((err as Error).message ?? 'Error saving factory run usage.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!selectedUsage) return;
    setLoading(true);
    setError('');
    try {
      await deleteFactoryRunUsage(selectedUsage.factoryRunUsageId);
      await loadFactoryRunUsages(true); // Reload data
      setError('Uso de Factory Run eliminado exitosamente.');
    } catch (err) {
      setError((err as Error).message ?? 'Error deleting factory run usage.');
    } finally {
      setLoading(false);
      setSelectedUsage(null);
    }
  };

  return (
    <IonPage className="factoryRunUsage-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Uso de Factory Run — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding" ref={contentRef}>
        <IonRefresher slot="fixed" onIonRefresh={doRefresh}>
          <IonRefresherContent pullingText="Pull to refresh" refreshingText="Refreshing..."></IonRefresherContent>
        </IonRefresher>

        <IonSearchbar
          placeholder="Buscar por referencia o modelo"
          value={searchTerm}
          onIonInput={handleSearch}
          debounce={300}
          className="factoryRunUsage-searchbar"
        ></IonSearchbar>

        {isAdmin && (
          <IonButton expand="block" onClick={openCreateModal} className="factoryRunUsage-add-button">
            <IonIcon icon={addOutline} slot="start" />
            Registrar Uso de LLM
          </IonButton>
        )}

        <IonList className="factoryRunUsage-list">
          {factoryRunUsages.length === 0 && !loading && !error && (
            <IonItem>
              <IonLabel>No se encontraron usos de Factory Run.</IonLabel>
            </IonItem>
          )}
          {factoryRunUsages.map((usage) => (
            <IonItem key={usage.factoryRunUsageId} className="factoryRunUsage-item">
              <div className="factoryRunUsage-item-content">
                <IonLabel>
                  <h2>Ref: <strong>{usage.factoryRunRef}</strong></h2>
                  <p>Modelo: {usage.modelName}</p>
                  <p>Tokens: {usage.totalTokens} (P:{usage.promptTokens} | C:{usage.completionTokens})</p>
                  <p>Costo: ${usage.costUSD.toFixed(2)} USD</p>
                  <p>Fecha: {toHermosillo(usage.timestamp)}</p>
                </IonLabel>
                {isAdmin && (
                  <div className="factoryRunUsage-actions">
                    <IonButton fill="clear" onClick={() => openEditModal(usage)}>
                      <IonIcon icon={createOutline} color="primary" />
                    </IonButton>
                    <IonButton fill="clear" onClick={() => { setSelectedUsage(usage); setShowDeleteAlert(true); }}>
                      <IonIcon icon={trashOutline} color="danger" />
                    </IonButton>
                  </div>
                )}
              </div>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={loadMoreItems}>
          <IonInfiniteScrollContent loadingText="Cargando más usos..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonLoading isOpen={loading && factoryRunUsages.length === 0} message="Cargando usos..." />

        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.toLowerCase().includes('error') ? 'danger' : 'success'}
        />

        {/* Create/Edit Modal */}
        <IonModal isOpen={showFormModal} onDidDismiss={() => { setShowFormModal(false); setSelectedUsage(null); }} className="factoryRunUsage-modal">
          <IonContent className="ion-padding">
            <div className="factoryRunUsage-modal-header">
              <h2>{isEditing ? 'Editar Uso de LLM' : 'Registrar Nuevo Uso de LLM'}</h2>
              <IonButton fill="clear" onClick={() => setShowFormModal(false)}>
                <IonIcon icon={closeOutline} />
              </IonButton>
            </div>

            <div className="wizard-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Referencia de Factory Run *"
                  labelPlacement="floating"
                  value={formState.factoryRunRef}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, factoryRunRef: e.detail.value! }))}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
